dataprocessscript.script:
import java.util.Properties;
import java.io.InputStream;
import java.io.ByteArrayInputStream;
import java.io.File;
import java.io.FileOutputStream;
import groovy.json.JsonSlurper;
import groovy.json.JsonOutput;

for (int i = 0; i < dataContext.getDataCount(); i++) {
    InputStream is = dataContext.getStream(i);
    Properties props = dataContext.getProperties(i);
    is.close();

    File manifestFile = new File("D:\\BoomiLab\\Project01\\source\\chunks\\manifest.json");
    def manifest = new JsonSlurper().parse(manifestFile);
    long actualBytes = Long.parseLong(props.getProperty("document.dynamic.userdefined.DDP_P01_ACTUAL_BYTES", "0"));
    long maxHeap = Long.parseLong(props.getProperty("document.dynamic.userdefined.DDP_P01_MAX_HEAP_BYTES", "0"));

    def proof = [
        status: props.getProperty("document.dynamic.userdefined.DDP_P01_INTEGRITY_STATUS", "UNKNOWN"),
        sourceFile: props.getProperty("document.dynamic.userdefined.DDP_P01_STREAM_FILE", ""),
        sourceBytes: actualBytes,
        sourceGiB: actualBytes / 1073741824.0,
        expectedSha256: props.getProperty("document.dynamic.userdefined.DDP_P01_EXPECTED_SHA256", ""),
        actualSha256: props.getProperty("document.dynamic.userdefined.DDP_P01_ACTUAL_SHA256", ""),
        maxHeapBytes: maxHeap,
        maxHeapGiB: maxHeap / 1073741824.0,
        manifestChunks: manifest.chunks.size(),
        manifestGeneratedBytes: manifest.generatedBytes,
        manifestEmployees: manifest.employeesGenerated,
        bufferBytes: 65536
    ];

    String json = JsonOutput.prettyPrint(JsonOutput.toJson(proof));
    File evidenceDir = new File("D:\\BoomiLab\\Project01\\evidence");
    evidenceDir.mkdirs();
    File proofFile = new File(evidenceDir, "P01.15-12gb-source-proof.json");
    FileOutputStream fos = new FileOutputStream(proofFile, false);
    try { fos.write(json.getBytes("UTF-8")); } finally { fos.close(); }

    dataContext.storeStream(new ByteArrayInputStream(json.getBytes("UTF-8")), props);
}
